@extends('layouts.app',['title'=>'Inventory ledger']) @section('content')<div class="page-header"><div><h1 class="page-title">Inventory ledger</h1><p class="page-subtitle">Every stock change has a before value, after value, source and user.</p></div><a class="btn btn-primary" href="{{ route('inventory.adjustments') }}">New adjustment</a></div><section class="panel"><div class="panel-header"><form method="GET" class="flex w-full max-w-xl gap-2"><select name="book_id"><option value="">All books</option>@foreach($books as $book)<option value="{{ $book->id }}" @selected(request('book_id')==$book->id)>{{ $book->title }}</option>@endforeach</select><button class="btn btn-secondary">Filter</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Timestamp</th><th>Book</th><th>Type</th><th>Before</th><th>Change</th><th>After</th><th>By</th><th>Reason</th></tr></thead><tbody>@forelse($movements as $movement)<tr><td>{{ $movement->created_at->format('d M Y H:i') }}</td><td>{{ $movement->book->title }}</td><td class="capitalize">{{ str_replace('_',' ',$movement->type) }}</td><td>{{ $movement->quantity_before }}</td><td class="font-semibold {{ $movement->quantity_change<0?'text-rose-700':'text-emerald-700' }}">{{ $movement->quantity_change>0?'+':'' }}{{ $movement->quantity_change }}</td><td>{{ $movement->quantity_after }}</td><td>{{ $movement->user?->name ?? 'System' }}</td><td>{{ $movement->reason ?: '—' }}</td></tr>@empty<tr><td colspan="8" class="empty">No inventory movements found.</td></tr>@endforelse</tbody></table></div><div class="border-t border-slate-200 px-4 py-3">{{ $movements->links() }}</div></section>@endsection
